-- ─── 0. HELPER: deterministic text → UUID ────────────────────────────────────
-- Converts any text key like 'py-l1-c1' to a stable UUID so FK links work.
CREATE OR REPLACE FUNCTION cq_id(t TEXT) RETURNS UUID
LANGUAGE SQL IMMUTABLE AS $$
  SELECT (
    substring(md5(t),  1, 8) || '-' ||
    substring(md5(t),  9, 4) || '-' ||
    substring(md5(t), 13, 4) || '-' ||
    substring(md5(t), 17, 4) || '-' ||
    substring(md5(t), 21, 12)
  )::uuid;
$$;

-- ─── 1. ADD MISSING COLUMNS ───────────────────────────────────────────────────
ALTER TABLE chapters
  ADD COLUMN IF NOT EXISTS total_lessons INTEGER NOT NULL DEFAULT 0;

-- ─── 2. CLEAR EXISTING LEVEL DATA (safe re-run) ───────────────────────────────
DELETE FROM quiz_questions;
DELETE FROM lessons;
DELETE FROM chapters;

