  (cq_id('c-l3-c1-l2'),cq_id('c-l3-c1'),'c','calloc & realloc',     'Zero-init and resizable memory','theory','advanced',2,80,18,
   E'# calloc/realloc\n\n```c\nint *arr=(int*)calloc(5,sizeof(int));\narr=(int*)realloc(arr,10*sizeof(int));\nfree(arr);\n```',ARRAY['c','calloc','realloc'],18,true),
