-- =============================================================================
-- QUIZ QUESTIONS
-- (options must be JSONB — use proper JSON array strings)
-- =============================================================================

INSERT INTO quiz_questions (id, lesson_id, question, options, correct_option_index, explanation, code_snippet)
VALUES
  -- Python L1 types quiz
  (cq_id('q-py-l1-c1-l3-1'), cq_id('py-l1-c1-l3'),
   'Which of the following is an integer in Python?',
   '["3.14","\"42\"","42","True"]'::jsonb, 2,
   '42 is an integer literal. 3.14 is a float, "42" is a string, True is a bool.', NULL),
  (cq_id('q-py-l1-c1-l3-2'), cq_id('py-l1-c1-l3'),
   'What type does Python assign to x = 3.0?',
   '["int","float","str","complex"]'::jsonb, 1,
   'A number with a decimal point is inferred as float.',
   E'x = 3.0\nprint(type(x))  # <class float>'),
  (cq_id('q-py-l1-c1-l3-3'), cq_id('py-l1-c1-l3'),
   'Which keyword makes a variable constant in Python?',
   '["const","final","val","None of the above"]'::jsonb, 3,
   'Python has no built-in constant keyword; the convention is UPPER_CASE naming.', NULL),
  (cq_id('q-py-l1-c1-l3-4'), cq_id('py-l1-c1-l3'),
   'What is the result of type(True)?',
   '["int","bool","str","NoneType"]'::jsonb, 1,
   'bool is a subclass of int in Python, but type(True) returns <class bool>.', NULL),

  -- JavaScript L1 types quiz
  (cq_id('q-js-l1-c1-l3-1'), cq_id('js-l1-c1-l3'),
   'Which keyword declares a block-scoped, reassignable variable?',
   '["var","let","const","function"]'::jsonb, 1,
   'let is block-scoped and can be reassigned. const is immutable, var is function-scoped.', NULL),
  (cq_id('q-js-l1-c1-l3-2'), cq_id('js-l1-c1-l3'),
   'What does typeof "42" return?',
   '["number","string","undefined","object"]'::jsonb, 1,
   '"42" is wrapped in quotes so it is a string literal.',
   E'console.log(typeof "42"); // "string"'),
  (cq_id('q-js-l1-c1-l3-3'), cq_id('js-l1-c1-l3'),
   'Which value is falsy in JavaScript?',
   '["1","\"false\"","[]","0"]'::jsonb, 3,
   '0, "", null, undefined, NaN, and false are the six falsy values.', NULL),
  (cq_id('q-js-l1-c1-l3-4'), cq_id('js-l1-c1-l3'),
   'What is the result of 3 + "3" in JavaScript?',
   '["6","\"33\"","NaN","33"]'::jsonb, 1,
   'When + is used with a string, JS coerces the number to string and concatenates.',
   E'console.log(3 + "3"); // "33"'),

  -- Java L1 operators quiz
  (cq_id('q-java-l1-c1-l3-1'), cq_id('java-l1-c1-l3'),
   'What is the size of an int in Java?',
   '["2 bytes","4 bytes","8 bytes","Platform dependent"]'::jsonb, 1,
   'Java int is always 32-bit (4 bytes) regardless of platform.', NULL),
  (cq_id('q-java-l1-c1-l3-2'), cq_id('java-l1-c1-l3'),
   'Which of these is NOT a primitive type in Java?',
   '["int","String","boolean","char"]'::jsonb, 1,
   'String is a reference (object) type in Java, not a primitive.', NULL),
  (cq_id('q-java-l1-c1-l3-3'), cq_id('java-l1-c1-l3'),
   'What does == compare for objects in Java?',
   '["Value equality","Reference equality","Hash codes","Content equality"]'::jsonb, 1,
   '== checks if two references point to the same object. Use .equals() for value comparison.',
   E'String a=new String("hi");\nString b=new String("hi");\nSystem.out.println(a==b);      // false\nSystem.out.println(a.equals(b)); // true'),
  (cq_id('q-java-l1-c1-l3-4'), cq_id('java-l1-c1-l3'),
   'Which wrapper class corresponds to int?',
   '["Int","Integer","IntWrapper","Number"]'::jsonb, 1,
   'Java provides Integer as the boxed (object) version of the int primitive.', NULL);

